590→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
591→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
592→// Returns empty string if no valid prompt is found.
593→func ExtractFirstPrompt(content string) string {
594→	if content == "" {
595→		return ""
596→	}
597→
598→	// Prompts are separated by "\n\n---\n\n"
599→	// Find the first non-empty prompt
600→	prompts := strings.Split(content, "\n\n---\n\n")
601→	var firstPrompt string
602→	for _, p := range prompts {
603→		cleaned := strings.TrimSpace(p)
604→		// Skip empty prompts or prompts that are just dashes/separators
605→		if cleaned == "" || isOnlySeparators(cleaned) {
606→			continue
607→		}
608→		firstPrompt = cleaned
609→		break
610→	}
611→
612→	if firstPrompt == "" {
613→		return ""
614→	}
615→
616→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
617→}
