808→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
809→// about each session, including whether local logs have newer timestamps.
810→// repoRoot is used to compute per-session agent directories.
811→// Sessions without agent metadata are skipped (cannot determine target directory).
812→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
813→	var sessions []SessionRestoreInfo
814→
815→	totalSessions := len(summary.Sessions)
816→	// Check all sessions (0-based indexing)
817→	for i := range totalSessions {
818→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
819→		if err != nil || content == nil || len(content.Transcript) == 0 {
820→			continue
821→		}
822→
823→		sessionID := content.Metadata.SessionID
824→		if sessionID == "" || content.Metadata.Agent == "" {
825→			continue
826→		}
827→
828→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
829→		if agErr != nil {
830→			continue
831→		}
832→
833→		// Compute transcript path from current repo location for cross-machine portability.
834→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
835→		if dirErr != nil {
836→			continue
837→		}
838→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
839→
840→		localTime := paths.GetLastTimestampFromFile(localPath)
841→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
842→		status := ClassifyTimestamps(localTime, checkpointTime)
843→
844→		sessions = append(sessions, SessionRestoreInfo{
845→			SessionID:      sessionID,
846→			Prompt:         ExtractFirstPrompt(content.Prompts),
847→			Status:         status,
848→			LocalTime:      localTime,
849→			CheckpointTime: checkpointTime,
850→		})
851→	}
852→
853→	return sessions
854→}
