856→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
857→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
858→	// Local file doesn't exist (no timestamp found)
859→	if localTime.IsZero() {
860→		return StatusNew
861→	}
862→
863→	// Can't determine checkpoint time - treat as new/safe
864→	if checkpointTime.IsZero() {
865→		return StatusNew
866→	}
867→
868→	// Compare timestamps
869→	if localTime.After(checkpointTime) {
870→		return StatusLocalNewer
871→	}
872→	if checkpointTime.After(localTime) {
873→		return StatusCheckpointNewer
874→	}
875→	return StatusUnchanged
876→}
