		if branchName != "master" {
			t.Errorf("branchName = %q, want %q", branchName, "master")
		}
	})

	t.Run("returns false when on feature branch", func(t *testing.T) {
		tmpDir := t.TempDir()
		repo, err := git.PlainInit(tmpDir, false)
		if err != nil {
			t.Fatalf("failed to init repo: %v", err)
